def solve(n, fixed):
    cols=set(); d1=set(); d2=set(); q=[None]*n
    # We'll order rows maybe fixed first? use recursion select min domain
    rows=list(range(n))
    def rec(count):
        if count==n:
            return q.copy()
        # choose unassigned row with smallest valid candidates
        best=None; candbest=None
        for r in range(n):
            if q[r] is None:
                if r in fixed:
                    cands=[fixed[r]]
                else:
                    cands=range(n)
                valid=[]
                for c in cands:
                    if c not in cols and r-c not in d1 and r+c not in d2:
                        valid.append(c)
                if candbest is None or len(valid)<len(candbest):
                    best=r; candbest=valid
                    if len(valid)==0: break
        if not candbest:
            return None
        r=best
        # maybe try in order
        for c in candbest:
            q[r]=c; cols.add(c); d1.add(r-c); d2.add(r+c)
            res=rec(count+1)
            if res is not None: return res
            cols.remove(c); d1.remove(r-c); d2.remove(r+c); q[r]=None
        return None
    return rec(0)
